  /**
   * @method
   * @name cryptomus#fetchMarkets
   * @description retrieves data on all markets for the exchange
   * @see https://doc.cryptomus.com/personal/market-cap/tickers
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response = awaitValue(
                            this->publicGetV2UserApiExchangeMarkets(params));
                        //
                        //     {
                        //         "result": [
                        //             {
                        //                 "id": "01JHN5EFT64YC4HR9KCGM5M65D",
                        //                 "symbol": "POL_USDT",
                        //                 "baseCurrency": "POL",
                        //                 "quoteCurrency": "USDT",
                        //                 "baseMinSize": "1.00000000",
                        //                 "quoteMinSize": "5.00000000",
                        //                 "baseMaxSize": "50000.00000000",
                        //                 "quoteMaxSize":
                        //                 "10000000000.00000000", "basePrec":
                        //                 "1", "quotePrec": "4"
                        //             },
                        //             ...
                        //         ]
                        //     }
                        //
                        ccxt::any result = this->safeList(
                            response, std::string("result"), ccxt::list{});
                        return this->parseMarkets(result);
                      })
        .share();
  }

  ccxt::any parseMarket(ccxt::any market) override {
    //
    //     {
    //         "id": "01JHN5EFT64YC4HR9KCGM5M65D",
    //         "symbol": "POL_USDT",
    //         "baseCurrency": "POL",
    //         "quoteCurrency": "USDT",
    //         "baseMinSize": "1.00000000",
    //         "quoteMinSize": "5.00000000",
    //         "baseMaxSize": "50000.00000000",
    //         "quoteMaxSize": "10000000000.00000000",
    //         "basePrec": "1",
    //         "quotePrec": "4"
    //     }
    //
    ccxt::any marketId = this->safeString(market, std::string("symbol"));
    if (isTrue(isEqual(marketId, ccxt::any{}))) {
      throw ExchangeError(toString(
          add(this->id, std::string(" parseMarket() missing marketId"))));
    }
    ccxt::any parts = split(marketId, std::string("_"));
    ccxt::any baseId = ::getValue(parts, 0);
    ccxt::any quoteId = ::getValue(parts, 1);
    ccxt::any base = this->safeCurrencyCode(baseId);
    ccxt::any quote = this->safeCurrencyCode(quoteId);
    ccxt::any fees = this->safeDict(this->fees, std::string("trading"));
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), marketId},
        {std::string("symbol"), add(add(base, std::string("/")), quote)},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("active"), true},
        {std::string("type"), std::string("spot")},
        {std::string("subType"), ccxt::any{}},
        {std::string("spot"), true},
        {std::string("margin"), false},
        {std::string("swap"), false},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("contract"), false},
        {std::string("settle"), ccxt::any{}},
        {std::string("settleId"), ccxt::any{}},
        {std::string("contractSize"), ccxt::any{}},
        {std::string("linear"), ccxt::any{}},
        {std::string("inverse"), ccxt::any{}},
        {std::string("taker"), this->safeNumber(fees, std::string("taker"))},
        {std::string("maker"), this->safeNumber(fees, std::string("maker"))},
        {std::string("percentage"),
         this->safeBool(fees, std::string("percentage"))},
        {std::string("tierBased"), ccxt::any{}},
        {std::string("feeSide"),
         this->safeString(fees, std::string("feeSide"))},
        {std::string("expiry"), ccxt::any{}},
        {std::string("expiryDatetime"), ccxt::any{}},
        {std::string("strike"), ccxt::any{}},
        {std::string("optionType"), ccxt::any{}},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"),
              this->parseNumber(this->parsePrecision(
                  this->safeString(market, std::string("quotePrec"))))},
             {std::string("price"),
              this->parseNumber(this->parsePrecision(
                  this->safeString(market, std::string("basePrec"))))},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("quoteMinSize"))},
                  {std::string("max"),
                   this->safeNumber(market, std::string("quoteMaxSize"))},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("baseMinSize"))},
                  {std::string("max"),
                   this->safeNumber(market, std::string("baseMaxSize"))},
              }},
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
         }},
        {std::string("created"), ccxt::any{}},
        {std::string("info"), market},
    });
  }

  /**
   * @method
   * @name cryptomus#fetchCurrencies
   * @description fetches all available currencies on an exchange
   * @see https://doc.cryptomus.com/personal/market-cap/assets
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an associative dictionary of currencies
   */
  std::shared_future<ccxt::any>
  fetchCurrencies(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response = awaitValue(
                            this->publicGetV1ExchangeMarketAssets(params));
                        //
                        //     {
                        //         'state': '0',
                        //         'result': [
                        //             {
                        //                 'currency_code': 'USDC',
                        //                 'network_code': 'bsc',
                        //                 'can_withdraw': true,
                        //                 'can_deposit': true,
                        //                 'min_withdraw': '1.00000000',
                        //                 'max_withdraw': '10000000.00000000',
                        //                 'max_deposit': '10000000.00000000',
                        //                 'min_deposit': '1.00000000'
                        //             },
                        //             ...
                        //         ]
                        //     }
                        //
                        ccxt::any coins =
                            this->safeList(response, std::string("result"));
                        ccxt::any groupedById =
                            this->groupBy(coins, std::string("currency_code"));
                        ccxt::any groupedArray = getObjectValues(groupedById);
                        return this->parseCurrencies(groupedArray);
                      })
        .share();
  }

  ccxt::any parseCurrency(ccxt::any rawCurrency) override {
    // currency here is array of networks
    ccxt::any id =
        ccxt::any{}; // all entries have same id, as they were grouped by
    ccxt::any code = ccxt::any{};
    ccxt::any networks = ccxt::dict{};
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(rawCurrency));
         postFixIncrement(i)) {
      ccxt::any networkEntry = ::getValue(rawCurrency, i);
      // set ID on first loop
      if (isTrue(isEqual(id, ccxt::any{}))) {
        id = this->safeString(networkEntry, std::string("currency_code"));
        code = this->safeCurrencyCode(id);
      }
      ccxt::any networkId =
          this->safeString(networkEntry, std::string("network_code"));
      ccxt::any networkCode = this->networkIdToCode(networkId, code);
      if (isTrue(!isEqual(networkCode, ccxt::any{}))) {
        ::setValue(
            networks, networkCode,
            ccxt::dict{
                {std::string("id"), networkId},
                {std::string("network"), networkCode},
                {std::string("limits"),
                 ccxt::dict{
                     {std::string("withdraw"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber(networkEntry,
                                            std::string("min_withdraw"))},
                          {std::string("max"),
                           this->safeNumber(networkEntry,
                                            std::string("max_withdraw"))},
                      }},
                     {std::string("deposit"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber(networkEntry,
                                            std::string("min_deposit"))},
                          {std::string("max"),
                           this->safeNumber(networkEntry,
                                            std::string("max_deposit"))},
                      }},
                 }},
                {std::string("active"), ccxt::any{}},
                {std::string("deposit"),
                 this->safeBool(networkEntry, std::string("can_deposit"))},
                {std::string("withdraw"),
                 this->safeBool(networkEntry, std::string("can_withdraw"))},
                {std::string("fee"), ccxt::any{}},
                {std::string("precision"), ccxt::any{}},
                {std::string("info"), networkEntry},
            });
      }
    }
    return this->safeCurrencyStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("code"), code},
        {std::string("networks"), networks},
        {std::string("info"), rawCurrency},
    });
  }

  /**
   * @method
   * @name cryptomus#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see https://doc.cryptomus.com/personal/market-cap/tickers
   * @param {string[]} [symbols] unified symbols of the markets to fetch the
   * ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        symbols = this->marketSymbols(symbols);
                        ccxt::any response = awaitValue(
                            this->publicGetV1ExchangeMarketTickers(params));
                        //
                        //     {
                        //         "data": [
                        //         {
                        //             "currency_pair": "MATIC_USDT",
                        //             "last_price": "0.342",
                        //             "base_volume": "1676.84092771",
                        //             "quote_volume": "573.48033609043"
                        //         },
                        //         ...
                        //     }
                        //
                        ccxt::any data =
                            this->safeList(response, std::string("data"));
                        return this->parseTickers(data, symbols);
                      })
        .share();
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "currency_pair": "XMR_USDT",
    //         "last_price": "158.04829772",
    //         "base_volume": "0.35185785",
    //         "quote_volume": "55.523761128544"
    //     }
    //
    ccxt::any marketId = this->safeString(ticker, std::string("currency_pair"));
    market = this->safeMarket(marketId, market);
    ccxt::any symbol = ::getValue(market, std::string("symbol"));
    ccxt::any last = this->safeString(ticker, std::string("last_price"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), ccxt::any{}},
            {std::string("datetime"), ccxt::any{}},
            {std::string("high"), ccxt::any{}},
            {std::string("low"), ccxt::any{}},
            {std::string("bid"), ccxt::any{}},
            {std::string("bidVolume"), ccxt::any{}},
            {std::string("ask"), ccxt::any{}},
            {std::string("askVolume"), ccxt::any{}},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"), ccxt::any{}},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), ccxt::any{}},
            {std::string("change"), ccxt::any{}},
            {std::string("percentage"), ccxt::any{}},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"),
             this->safeString(ticker, std::string("base_volume"))},
            {std::string("quoteVolume"),
             this->safeString(ticker, std::string("quote_volume"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name cryptomus#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://doc.cryptomus.com/personal/market-cap/orderbook
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.level] 0 or 1 or 2 or 3 or 4 or 5 - the level of
   * volume
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("currencyPair"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any level = 0;
                 ccxt::any levelparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrderBook"),
                     std::string("level"), level);
                 level = ::getValue(levelparamsVariable, 0);
                 params = ::getValue(levelparamsVariable, 1);
                 ::setValue(request, std::string("level"), level);
                 ccxt::any response = awaitValue(
                     this->publicGetV1ExchangeMarketOrderBookCurrencyPair(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "data": {
                 //             "timestamp": "1730138702",
                 //             "bids": [
                 //                 {
                 //                     "price": "2250.00",
                 //                     "quantity": "1.00000"
                 //                 }
                 //             ],
                 //             "asks": [
                 //                 {
                 //                     "price": "2428.69",
                 //                     "quantity": "0.16470"
                 //                 }
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any timestamp =
                     this->safeTimestamp(data, std::string("timestamp"));
                 return this->parseOrderBook(
                     data, symbol, timestamp, std::string("bids"),
                     std::string("asks"), std::string("price"),
                     std::string("quantity"));
               })
        .share();
  }

